def git(*args: str) -> str:
    try:
        out = subprocess.run(["git", *args], cwd=REPO, capture_output=True, text=True, check=False)
    except FileNotFoundError:
        return ""
    return out.stdout.strip() if out.returncode == 0 else ""

class Report:
    """Accumulates findings so every check runs even after one fails."""

    def __init__(self) -> None:
        self.failures: list[str] = []
        self.warnings: list[str] = []

    def fail(self, check: str, message: str) -> None:
        self.failures.append(f"{check}: {message}")
        print(f"  FAIL  {check}: {message}")

    def warn(self, check: str, message: str) -> None:
        self.warnings.append(f"{check}: {message}")
        print(f"  WARN  {check}: {message}")

    def ok(self, check: str, message: str) -> None:
        print(f"  ok    {check}: {message}")
